import sys


def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    N = int(next(iterator))

    # comp[i] armazenará o ID do componente do candidato i (1-indexado).
    # Se o candidato não tiver nenhum amigo, comp[i] = 0.
    comp = [0] * (N + 1)
    comp_id = 1

    for i in range(1, N + 1):
        row = next(iterator)
        if comp[i] == 0:
            # Encontrar amigos de i
            friends = []
            for j in range(N):
                if row[j] == '1':
                    friends.append(j + 1)

            if friends:
                comp[i] = comp_id
                for friend in friends:
                    comp[friend] = comp_id
                comp_id += 1

    E = int(next(iterator))

    visited_comp = [0] * comp_id
    output = []

    for t in range(1, E + 1):
        k = int(next(iterator))
        has_friends = False
        for _ in range(k):
            cand = int(next(iterator))
            c_id = comp[cand]
            if not has_friends and c_id > 0:
                if visited_comp[c_id] == t:
                    has_friends = True
                else:
                    visited_comp[c_id] = t

        if has_friends:
            output.append('S')
        else:
            output.append('N')

    sys.stdout.write('\n'.join(output) + '\n')


